from __future__ import annotations

import os
import subprocess
import sys


def execute(cmd: str) -> int:
    """Execute an external command and return its exit status."""
    print("EXECUTE:", cmd)
    sys.stdout.flush()
    return subprocess.call(cmd, shell=True)


def execute_required(cmd: str, description: str, expected_outputs: tuple[str, ...] | list[str] = ()) -> bool:
    """Run a command and assert exit status plus required file outputs."""
    rtv = execute(cmd)

    if rtv != 0:
        print(f"ERROR: {description} failed with exit code {rtv}.")
        return False

    missing_outputs = [
        output_path for output_path in expected_outputs if not os.path.isfile(output_path)
    ]
    if missing_outputs:
        print(
            f"ERROR: {description} returned success but did not create required output files:"
        )
        for output_path in missing_outputs:
            print(f"  - {output_path}")
        return False

    return True

